COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."app_key" IS '应用标识（区分不同微服务的审计记录）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."operator_id" IS '操作人 ID（来自 RequestContext 透传）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."operator_name" IS '操作人姓名（便于直接展示）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."audit_type" IS '审计类型编码（1=操作/2=登录/3=数据/4=权限/5=配置/6=文件/7=接口/8=系统）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."action" IS '操作行为编码（1=新增/2=修改/3=删除/4=查询/5=导入/6=导出/7=上传/8=下载/99=其他）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."module" IS '模块名称（如：用户管理、代码生成等）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."content" IS '操作内容描述（SpEL 解析后的最终文本）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."business_no" IS '业务流水号（关联业务单据）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."ip_address" IS '请求来源 IP 地址';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."request_params" IS '请求参数 JSON（已脱敏/截断，最大 10KB）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."response_result" IS '响应结果 JSON（已脱敏/截断，默认不记录）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."diff_before_snapshot" IS '变更前快照 JSON（仅 @Audit(recordDiff=true) 时写入）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."diff_after_snapshot" IS '变更后快照 JSON（仅 @Audit(recordDiff=true) 时写入）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."error_message" IS '异常信息（业务方法抛异常时记录）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."cost_time" IS '执行耗时（毫秒）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."trace_id" IS '链路追踪 ID（独立列，支持索引查询）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."operation_time" IS '操作时间（业务方法执行时刻）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."status" IS '执行状态（1=成功/0=失败）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_comm_audit_log"."created_at" IS '审计日志落库时刻';
CREATE INDEX "idx_ydsz_comm_audit_log_action" ON "public"."ydsz_comm_audit_log" USING btree ("action" ASC NULLS LAST, "operation_time" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_comm_audit_log_app_key" ON "public"."ydsz_comm_audit_log" USING btree ("app_key" ASC NULLS LAST, "operation_time" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_comm_audit_log_module_action" ON "public"."ydsz_comm_audit_log" USING btree ("module" ASC NULLS LAST, "action" ASC NULLS LAST, "operation_time" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_comm_audit_log_operation_time" ON "public"."ydsz_comm_audit_log" USING btree ("operation_time" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_comm_audit_log_operator_id" ON "public"."ydsz_comm_audit_log" USING btree ("operator_id" ASC NULLS LAST, "operation_time" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_comm_audit_log_status" ON "public"."ydsz_comm_audit_log" USING btree ("status" ASC NULLS LAST, "operation_time" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_comm_audit_log_tenant_time" ON "public"."ydsz_comm_audit_log" USING btree ("tenant_id" ASC NULLS LAST, "operation_time" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_comm_audit_log_trace_id" ON "public"."ydsz_comm_audit_log" USING btree ("trace_id" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_comm_outbox" CASCADE;

CREATE TABLE "public"."ydsz_comm_outbox" (
                                             "id" character varying(36) NOT NULL,
                                             "aggregate_type" character varying(128) NOT NULL,
                                             "aggregate_id" character varying(36) NOT NULL,
                                             "event_type" character varying(128) NOT NULL,
                                             "payload" text NOT NULL,
                                             "status" character varying(15) NOT NULL DEFAULT 'PENDING'::character varying,
                                             "retry_count" bigint NOT NULL DEFAULT 0,
                                             "max_retries" bigint NOT NULL DEFAULT 5,
                                             "next_retry_at" timestamp(3) without time zone,
                                             "error_message" text,
                                             "schema_version" integer NOT NULL DEFAULT 1,
                                             "is_compressed" smallint NOT NULL DEFAULT 0,
                                             "trace_id" character varying(36),
                                             "idempotency_key" character varying(64),
                                             "sent_at" timestamp(3) without time zone,
                                             "sort" integer DEFAULT 0,
                                             "revision" integer DEFAULT 0,
                                             "tenant_id" character varying(36),
                                             "is_deleted" smallint NOT NULL DEFAULT 0,
                                             "created_by" character varying(36) DEFAULT NULL::character varying,
                                             "created_at" timestamp(3) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
                                             "updated_by" character varying(36) DEFAULT NULL::character varying,
                                             "updated_at" timestamp(3) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
                                             CONSTRAINT "pk_ydsz_comm_outbox" PRIMARY KEY (id),
                                             CONSTRAINT "ck_ydsz_comm_outbox_status" CHECK (status::text = ANY (ARRAY['PENDING'::character varying, 'PROCESSING'::character varying, 'SENT'::character varying, 'DEAD_LETTER'::character varying]::text[]))
    );
COMMENT ON TABLE "public"."ydsz_comm_outbox" IS '事务性 Outbox 表：存储领域事件，保障业务写操作与事件投递的事务一致性';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."id" IS '消息唯一标识（Snowflake ID）';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."aggregate_type" IS '聚合根类型（如 Order, User）';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."aggregate_id" IS '聚合根 ID';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."event_type" IS '事件类型（如 OrderCreated）';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."payload" IS '事件负载 JSON（最大 4MB）';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."status" IS '投递状态';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."retry_count" IS '当前重试次数';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."max_retries" IS '最大重试次数';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."next_retry_at" IS '下次重试时间（指数退避）';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."error_message" IS '最后一次失败的错误信息';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."schema_version" IS '事件 schema 版本（向前兼容）';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."compressed" IS 'payload 是否 GZIP 压缩存储';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."trace_id" IS '链路追踪 ID';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."idempotency_key" IS '幂等去重 ID';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."sent_at" IS '投递成功时间';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_comm_outbox"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_comm_outbox_aggregate" ON "public"."ydsz_comm_outbox" USING btree ("aggregate_type" ASC NULLS LAST, "aggregate_id" ASC NULLS LAST, "created_at" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_comm_outbox_dedup" ON "public"."ydsz_comm_outbox" USING btree ("idempotency_key" ASC NULLS LAST, "status" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_outbox_pending" ON "public"."ydsz_comm_outbox" USING btree ("status" ASC NULLS LAST, "created_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_outbox_processing" ON "public"."ydsz_comm_outbox" USING btree ("status" ASC NULLS LAST, "updated_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_outbox_retry" ON "public"."ydsz_comm_outbox" USING btree ("status" ASC NULLS LAST, "next_retry_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_outbox_sent_at" ON "public"."ydsz_comm_outbox" USING btree ("status" ASC NULLS LAST, "sent_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_outbox_tenant" ON "public"."ydsz_comm_outbox" USING btree ("tenant_id" ASC NULLS LAST, "status" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_comm_outbox_archive" CASCADE;

CREATE TABLE "public"."ydsz_comm_outbox_archive" (
                                                     "id" character varying(36) NOT NULL,
                                                     "aggregate_id" character varying(36) NOT NULL,
                                                     "aggregate_type" character varying(128) DEFAULT NULL::character varying,
                                                     "event_type" character varying(256) NOT NULL,
                                                     "payload" text NOT NULL,
                                                     "status" character varying(16) NOT NULL,
                                                     "retry_count" integer NOT NULL DEFAULT 0,
                                                     "max_retries" integer NOT NULL DEFAULT 5,
                                                     "idempotency_key" character varying(128) DEFAULT NULL::character varying,
                                                     "trace_id" character varying(36) DEFAULT NULL::character varying,
                                                     "schema_version" integer NOT NULL DEFAULT 1,
                                                     "is_compressed" smallint NOT NULL DEFAULT 0,
                                                     "sent_at" timestamp without time zone,
                                                     "archived_at" timestamp without time zone NOT NULL,
                                                     "error_message" text,
                                                     "sort" integer DEFAULT 0,
                                                     "revision" integer DEFAULT 0,
                                                     "tenant_id" character varying(36) DEFAULT NULL::character varying,
                                                     "is_deleted" smallint NOT NULL DEFAULT 0,
                                                     "created_by" character varying(36) DEFAULT NULL::character varying,
                                                     "created_at" timestamp without time zone NOT NULL,
                                                     "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                     "updated_at" timestamp without time zone NOT NULL,
                                                     CONSTRAINT "ydsz_comm_outbox_archive_pkey" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_comm_outbox_archive" IS 'Outbox 事件归档表（已投递或已丢弃的消息）';
CREATE INDEX "idx_ydsz_comm_outbox_archive_aggregate" ON "public"."ydsz_comm_outbox_archive" USING btree ("aggregate_id" ASC NULLS LAST, "created_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_outbox_archive_archived_at" ON "public"."ydsz_comm_outbox_archive" USING btree ("archived_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_outbox_archive_created_at" ON "public"."ydsz_comm_outbox_archive" USING btree ("created_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_outbox_archive_event_type" ON "public"."ydsz_comm_outbox_archive" USING btree ("event_type" ASC NULLS LAST, "created_at" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_comm_search_dead_letter" CASCADE;

CREATE TABLE "public"."ydsz_comm_search_dead_letter" (
                                                         "id" character varying(36) NOT NULL,
                                                         "operation" character varying(20) NOT NULL,
                                                         "doc_type" character varying(64) DEFAULT NULL::character varying,
                                                         "document_id" character varying(36) DEFAULT NULL::character varying,
                                                         "document_json" text,
                                                         "error_msg" text,
                                                         "retry_count" integer NOT NULL DEFAULT 0,
                                                         "status" character varying(20) NOT NULL DEFAULT 'PENDING'::character varying,
                                                         "resolved_at" timestamp without time zone,
                                                         "sort" integer DEFAULT 0,
                                                         "revision" integer DEFAULT 0,
                                                         "tenant_id" character varying(36) DEFAULT '1'::character varying,
                                                         "is_deleted" smallint NOT NULL DEFAULT 0,
                                                         "created_by" character varying(36) DEFAULT NULL::character varying,
                                                         "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                         "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                         "updated_at" timestamp without time zone DEFAULT now(),
                                                         CONSTRAINT "pk_ydsz_comm_search_dead_letter" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_comm_search_dead_letter" IS '搜索索引死信队列：存储索引写入失败的操作，支持定时重放补偿';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."id" IS '自增主键';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."operation" IS '索引操作类型：UPSERT / DELETE / BULK';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."doc_type" IS '实体类型（project/wiki/user 等）';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."document_id" IS '文档主键（DELETE 操作时使用）';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."document_json" IS '文档 JSON（UPSERT/BULK 操作时使用）';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."error_msg" IS '最后一次失败原因（截断 2000 字符）';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."retry_count" IS '已重试次数，达到 5 次升级为 DISCARDED';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."status" IS '状态：PENDING-待处理 / RETRYING-处理中 / RESOLVED-已解决 / DISCARDED-已放弃(需人工介入)';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."resolved_at" IS '解决时间';
COMMENT ON COLUMN "public"."ydsz_comm_search_dead_letter"."created_at" IS '入队时间';
CREATE INDEX "idx_ydsz_comm_search_dead_letter_dlq_doc_type" ON "public"."ydsz_comm_search_dead_letter" USING btree ("doc_type" ASC NULLS LAST, "status" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_comm_search_dead_letter_dlq_status_created" ON "public"."ydsz_comm_search_dead_letter" USING btree ("status" ASC NULLS LAST, "created_at" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_comm_search_index_partitioned" CASCADE;

CREATE TABLE "public"."ydsz_comm_search_index_partitioned" (
                                                               "id" character varying(36) NOT NULL,
                                                               "doc_type" character varying(64) NOT NULL,
                                                               "title" character varying(512),
                                                               "subtitle" character varying(512),
                                                               "content" text,
                                                               "tags" text[],
                                                               "locale" character varying(16) DEFAULT 'zh-CN'::character varying,
                                                               "metadata" jsonb,
                                                               "active_flag" smallint NOT NULL DEFAULT 1,
                                                               "created_at" timestamp with time zone DEFAULT now(),
                                                               "updated_at" timestamp with time zone DEFAULT now(),
                                                               "sort" integer DEFAULT 0,
                                                               "status" integer DEFAULT 1,
                                                               "revision" integer DEFAULT 0,
                                                               "tenant_id" character varying(36) NOT NULL,
                                                               "is_deleted" smallint NOT NULL DEFAULT 0,
                                                               "created_by" character varying(36) DEFAULT NULL::character varying,
                                                               "updated_by" character varying(36),
                                                               CONSTRAINT "pk_search_partitioned" PRIMARY KEY (tenant_id, id, doc_type)
) PARTITION BY HASH (tenant_id);
COMMENT ON TABLE "public"."ydsz_comm_search_index_partitioned" IS '搜索全文索引分区表（按 tenant_id HASH 分区，原 ydzs_wiki_search_index 升级）';

DROP TABLE IF EXISTS "public"."ydsz_file_file_acl" CASCADE;

CREATE TABLE "public"."ydsz_file_file_acl" (
                                               "id" character varying(36) NOT NULL,
                                               "file_node_id" character varying(36) NOT NULL,
                                               "grantee_type" character varying(32) NOT NULL,
                                               "grantee_id" character varying(36) NOT NULL,
                                               "permission_mask" integer NOT NULL DEFAULT 0,
                                               "is_inherited" smallint NOT NULL DEFAULT 1,
                                               "is_owner" smallint NOT NULL DEFAULT 0,
                                               "status" character varying(32) DEFAULT NULL::character varying,
                                               "sort" integer DEFAULT 0,
                                               "revision" integer NOT NULL DEFAULT 0,
                                               "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                               "is_deleted" smallint NOT NULL DEFAULT 0,
                                               "created_by" character varying(36) DEFAULT NULL::character varying,
                                               "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                               "updated_by" character varying(36) DEFAULT NULL::character varying,
                                               "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                               CONSTRAINT "pk_ydsz_file_file_acl" PRIMARY KEY (id),
                                               CONSTRAINT "uk_ydsz_file_file_acl_file_grantee" UNIQUE (file_node_id, grantee_type, grantee_id)
);
COMMENT ON TABLE "public"."ydsz_file_file_acl" IS '文件级 ACL 权限（文件/文件夹级别的细粒度权限控制）';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."file_node_id" IS '文件节点ID';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."grantee_type" IS '授权对象类型：user / role / group / tenant';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."grantee_id" IS '授权对象ID（用户ID / 角色ID / 组ID / 租户ID）';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."permission_mask" IS '权限位掩码（read=1, write=2, delete=4, share=8, download=16）';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."is_inherited" IS '是否继承自父目录';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."is_owner" IS '是否为所有者（所有者拥有全部权限）';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_file_file_acl"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_file_file_acl_grantee" ON "public"."ydsz_file_file_acl" USING btree ("grantee_type" ASC NULLS LAST, "grantee_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_file_file_acl_tenant_is_deleted" ON "public"."ydsz_file_file_acl" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_file_file_comment" CASCADE;

CREATE TABLE "public"."ydsz_file_file_comment" (
                                                   "id" character varying(36) NOT NULL,
                                                   "file_node_id" character varying(36) NOT NULL,
                                                   "content" text NOT NULL,
                                                   "parent_comment_id" character varying(36) DEFAULT NULL::character varying,
                                                   "is_resolved" smallint NOT NULL DEFAULT 0,
                                                   "position" jsonb,
                                                   "is_edited" smallint NOT NULL DEFAULT 0,
                                                   "status" character varying(32) DEFAULT NULL::character varying,
                                                   "sort" integer DEFAULT 0,
                                                   "revision" integer NOT NULL DEFAULT 0,
                                                   "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                                   "is_deleted" smallint NOT NULL DEFAULT 0,
                                                   "created_by" character varying(36) DEFAULT NULL::character varying,
                                                   "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                   "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                   "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                   CONSTRAINT "pk_ydsz_file_file_comment" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_file_file_comment" IS '文件评论（支持文件级别的评论和回复，用于知识库协作讨论）';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."file_node_id" IS '关联的文件节点ID';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."content" IS '评论内容';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."parent_comment_id" IS '父评论ID（用于回复，null 表示顶级评论）';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."is_resolved" IS '是否已解决（用于批注功能）';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."position" IS '评论位置信息（JSON，用于文档内定位批注）';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."is_edited" IS '是否被编辑过';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_file_file_comment"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_file_file_comment_file_node_id" ON "public"."ydsz_file_file_comment" USING btree ("file_node_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_file_file_comment_parent_comment_id" ON "public"."ydsz_file_file_comment" USING btree ("parent_comment_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_file_file_comment_tenant_is_deleted" ON "public"."ydsz_file_file_comment" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_file_file_node" CASCADE;

CREATE TABLE "public"."ydsz_file_file_node" (
                                                "id" character varying(36) NOT NULL,
                                                "parent_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                                "name" character varying(255) NOT NULL,
                                                "node_type" character varying(32) NOT NULL,
                                                "suffix" character varying(64) DEFAULT NULL::character varying,
                                                "size" bigint NOT NULL DEFAULT 0,
                                                "storage_key" character varying(1024) DEFAULT NULL::character varying,
                                                "bucket_name" character varying(128) DEFAULT NULL::character varying,
                                                "mime_type" character varying(128) DEFAULT NULL::character varying,
                                                "path" character varying(1024) NOT NULL,
                                                "level" integer NOT NULL DEFAULT 0,
