DROP TABLE IF EXISTS "public"."ydsz_flow_definition" CASCADE;

CREATE TABLE "public"."ydsz_flow_definition" (
                                                 "id" character varying(36) NOT NULL,
                                                 "flow_code" character varying(64) NOT NULL,
                                                 "flow_name" character varying(128) NOT NULL,
                                                 "category" character varying(64) DEFAULT NULL::character varying,
                                                 "flow_version" character varying(32) NOT NULL,
                                                 "model_value" character varying(32) DEFAULT NULL::character varying,
                                                 "form_custom" character varying(8) DEFAULT NULL::character varying,
                                                 "form_path" character varying(1024) DEFAULT NULL::character varying,
                                                 "activity_status" integer NOT NULL DEFAULT 1,
                                                 "is_publish" integer NOT NULL DEFAULT 0,
                                                 "listener_type" character varying(32) DEFAULT NULL::character varying,
                                                 "listener_path" character varying(128) DEFAULT NULL::character varying,
                                                 "ext" jsonb,
                                                 "description" character varying(512) DEFAULT NULL::character varying,
                                                 "provider_trace_id" character varying(36) DEFAULT NULL::character varying,
                                                 "canary_percent" integer NOT NULL DEFAULT 0,
                                                 "canary_status" character varying(32) DEFAULT NULL::character varying,
                                                 "canary_strategy" character varying(32) DEFAULT NULL::character varying,
                                                 "canary_rollout_log" jsonb,
                                                 "locked_by" character varying(32) DEFAULT NULL::character varying,
                                                 "locked_at" timestamp without time zone,
                                                 "status" character varying(32) DEFAULT NULL::character varying,
                                                 "sort" integer DEFAULT 0,
                                                 "revision" integer NOT NULL DEFAULT 0,
                                                 "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                                 "is_deleted" smallint NOT NULL DEFAULT 0,
                                                 "created_by" character varying(36) DEFAULT NULL::character varying,
                                                 "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                 "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                 "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                 CONSTRAINT "pk_ydsz_flow_definition" PRIMARY KEY (id),
                                                 CONSTRAINT "uk_ydsz_flow_definition_flow_code_version" UNIQUE (flow_code, flow_version, tenant_id)
);
COMMENT ON TABLE "public"."ydsz_flow_definition" IS '流程定义表（流程模板元数据）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."flow_code" IS '流程编码（业务语义，如 project_initiation / contract_change）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."flow_name" IS '流程名称（前端展示）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."category" IS '流程类别（用于分类筛选，如「项目类」「合同类」「人事类」）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."flow_version" IS '流程版本号（如 v1 / v2，同一 flowCode 下不同版本独立发布）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."model_value" IS '设计器模型（CLASSICS=经典横向流转图，MIMIC=纵向审批面板）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."form_custom" IS '审批表单是否自定义（Y=自定义表单，N=系统内置表单）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."form_path" IS '审批表单路径（formCustom=Y 时为 Vue 组件路径，否则为表单定义 ID）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."activity_status" IS '激活状态（0=挂起不可发起新实例，1=激活正常接收新实例）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."is_publish" IS '发布状态（0=未发布草稿，1=已发布可发起，9=失效已废弃）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."listener_type" IS '监听器类型（NONE=无，GLOBAL=全局，FLOW=流程级）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."listener_path" IS '监听器 Spring Bean 路径（如 projectFlowListener）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."ext" IS '扩展字段 JSON（业务侧自定义元数据：超时配置/抄送规则/审批人默认值等）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."description" IS '流程描述（说明流程的业务用途与适用场景）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."provider_trace_id" IS '链路追踪 ID（跨系统全链路追踪，与 ydsz_provider_trace_id 协议对齐）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."canary_percent" IS '灰度比例 0-100（0=全量稳定版，100=全量灰度版，1-99 按策略切流）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."canary_status" IS '灰度状态（NONE=未启用，CANARYING=灰度中，PROMOTED=已全量，ROLLED_BACK=已回滚）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."canary_strategy" IS '灰度切流策略（USER_HASH=按发起人取模，RANDOM=随机，WHITELIST=白名单）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."canary_rollout_log" IS '灰度发布历史 JSON 数组（[{operatorId,operatorName,fromPercent,toPercent,operateAt,note}]）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."locked_by" IS '当前持锁人 ID（设计器协同编辑锁定，NULL=未锁定）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."locked_at" IS '加锁时间（超过 30 分钟可强制抢占）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_flow_definition"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_flow_definition_category" ON "public"."ydsz_flow_definition" USING btree ("category" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_definition_tenant_is_deleted" ON "public"."ydsz_flow_definition" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_flow_delegate_auth" CASCADE;

CREATE TABLE "public"."ydsz_flow_delegate_auth" (
