COMMENT ON TABLE "public"."ydsz_flow_delegate_auth" IS '流程委派代理表（长期授权规则）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."id" IS '主键 ID（Snowflake）';
