COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."owner_user_name" IS '授权人姓名（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."delegate_user_id" IS '被授权人（代理人）ID';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."delegate_user_name" IS '被授权人姓名（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."scope_type" IS '匹配模式（ALL=所有流程，FLOW=指定流程，FLOW_NODE=指定流程节点，ROLE=指定角色）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."flow_code" IS '流程编码（FLOW/FLOW_NODE 模式必填）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."node_code" IS '节点编码（FLOW_NODE 模式必填）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."role_code" IS '角色编码（ROLE 模式必填）';
