COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."end_time" IS '生效结束时间';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."auth_status" IS '授权状态（ENABLED=生效中，DISABLED=手动停用，EXPIRED=已过期，REVOKED=已撤销）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."reason" IS '授权原因（如「出差 3 天」「部门调整」）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."provider_trace_id" IS '链路追踪 ID';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_flow_delegate_auth"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_flow_delegate_auth_delegate_user_id" ON "public"."ydsz_flow_delegate_auth" USING btree ("delegate_user_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_delegate_auth_owner_user_id" ON "public"."ydsz_flow_delegate_auth" USING btree ("owner_user_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_delegate_auth_status_time" ON "public"."ydsz_flow_delegate_auth" USING btree ("auth_status" ASC NULLS LAST, "end_time" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_delegate_auth_tenant_is_deleted" ON "public"."ydsz_flow_delegate_auth" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_flow_event_subscription" CASCADE;

CREATE TABLE "public"."ydsz_flow_event_subscription" (
                                                         "id" character varying(36) NOT NULL,
