                                                         "definition_id" character varying(36) NOT NULL,
                                                         "flow_code" character varying(64) DEFAULT NULL::character varying,
                                                         "node_code" character varying(64) NOT NULL,
                                                         "node_name" character varying(128) DEFAULT NULL::character varying,
                                                         "event_type" character varying(32) NOT NULL,
                                                         "event_ref" character varying(64) NOT NULL,
                                                         "correlation_key" character varying(64) DEFAULT NULL::character varying,
                                                         "boundary_task_id" character varying(36) DEFAULT NULL::character varying,
                                                         "subscription_status" character varying(32) NOT NULL DEFAULT 'WAITING'::character varying,
                                                         "payload" jsonb,
                                                         "triggered_at" timestamp without time zone,
                                                         "trigger_source" character varying(32) DEFAULT NULL::character varying,
                                                         "cancel_reason" character varying(512) DEFAULT NULL::character varying,
                                                         "provider_trace_id" character varying(36) DEFAULT NULL::character varying,
                                                         "status" character varying(32) DEFAULT NULL::character varying,
                                                         "sort" integer DEFAULT 0,
                                                         "revision" integer NOT NULL DEFAULT 0,
                                                         "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                                         "is_deleted" smallint NOT NULL DEFAULT 0,
                                                         "created_by" character varying(36) DEFAULT NULL::character varying,
                                                         "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                         "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                         "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                         CONSTRAINT "pk_ydsz_flow_event_subscription" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_flow_event_subscription" IS '工作流事件订阅表（消息/错误/信号事件运行时等待）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."instance_id" IS '流程实例 ID';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."definition_id" IS '流程定义 ID';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."flow_code" IS '流程编码（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."node_code" IS '节点编码（事件捕获节点）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."node_name" IS '节点名称（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."event_type" IS '事件类型（MESSAGE=消息，ERROR=错误，SIGNAL=信号）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."event_ref" IS '事件引用标识（messageRef / errorRef / signalRef）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."correlation_key" IS '消息关联键（业务级匹配，SIGNAL 广播匹配时可空）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."boundary_task_id" IS '边界事件关联的 userTask ID（中间事件为 NULL）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."subscription_status" IS '订阅状态（WAITING=等待中，COMPLETED=已完成，CANCELLED=已取消）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."payload" IS '触发时携带的业务数据 JSON';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."triggered_at" IS '实际触发时间';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."trigger_source" IS '触发来源（API=外部系统调用，SERVICE_TASK=服务任务抛出，BOUNDARY=边界事件超时）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."cancel_reason" IS '取消原因';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."provider_trace_id" IS '链路追踪 ID';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_flow_event_subscription"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_flow_event_sub_type_status" ON "public"."ydsz_flow_event_subscription" USING btree ("tenant_id" ASC NULLS LAST, "event_type" ASC NULLS LAST, "status" ASC NULLS LAST, "correlation_key" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_event_subscription_correlation_key" ON "public"."ydsz_flow_event_subscription" USING btree ("correlation_key" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_event_subscription_event_ref" ON "public"."ydsz_flow_event_subscription" USING btree ("event_ref" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_event_subscription_instance_id" ON "public"."ydsz_flow_event_subscription" USING btree ("instance_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_event_subscription_subscription_status" ON "public"."ydsz_flow_event_subscription" USING btree ("subscription_status" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_event_subscription_tenant_is_deleted" ON "public"."ydsz_flow_event_subscription" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

