CREATE INDEX "idx_ydsz_flow_his_instance_tenant_is_deleted" ON "public"."ydsz_flow_his_instance" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_flow_his_task" CASCADE;

CREATE TABLE "public"."ydsz_flow_his_task" (
                                               "id" character varying(36) NOT NULL,
                                               "instance_id" character varying(36) NOT NULL,
                                               "task_id" character varying(36) NOT NULL,
                                               "flow_code" character varying(64) NOT NULL,
                                               "definition_id" character varying(36) NOT NULL,
                                               "node_code" character varying(64) NOT NULL,
                                               "node_name" character varying(128) DEFAULT NULL::character varying,
                                               "node_type" integer,
                                               "business_type" character varying(64) DEFAULT NULL::character varying,
                                               "business_id" character varying(36) DEFAULT NULL::character varying,
                                               "business_no" character varying(64) DEFAULT NULL::character varying,
                                               "flow_name" character varying(128) DEFAULT NULL::character varying,
                                               "title" character varying(128) DEFAULT NULL::character varying,
                                               "assignee_type" character varying(32) DEFAULT NULL::character varying,
                                               "assignee_id" character varying(36) DEFAULT NULL::character varying,
                                               "assignee_name" character varying(64) DEFAULT NULL::character varying,
                                               "perform_type" character varying(32) DEFAULT NULL::character varying,
                                               "approve_count" integer,
                                               "approve_finished" integer,
                                               "vote_pass_rate" numeric(20,6) DEFAULT NULL::numeric,
                                               "task_status" character varying(32) NOT NULL,
                                               "comment" character varying(512) DEFAULT NULL::character varying,
                                               "claim_at" timestamp without time zone,
                                               "finish_at" timestamp without time zone,
                                               "effective_time" timestamp without time zone,
                                               "duration_ms" bigint,
                                               "provider_trace_id" character varying(36) DEFAULT NULL::character varying,
                                               "iter_var" character varying(128) DEFAULT NULL::character varying,
                                               "status" character varying(32) DEFAULT NULL::character varying,
                                               "sort" integer DEFAULT 0,
                                               "revision" integer NOT NULL DEFAULT 0,
                                               "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                               "is_deleted" smallint NOT NULL DEFAULT 0,
                                               "created_by" character varying(36) DEFAULT NULL::character varying,
                                               "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                               "updated_by" character varying(36) DEFAULT NULL::character varying,
                                               "updated_at" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
                                               CONSTRAINT "pk_ydsz_flow_his_task" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_flow_his_task" IS '历史任务表（已完成任务归档，按月分区）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."instance_id" IS '流程实例 ID（归档时从 ydsz_flow_run_task.instance_id 复制）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."task_id" IS '原始任务 ID（指向源 ydsz_flow_run_task.id，归档后源表清理前可关联）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."flow_code" IS '流程编码';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."definition_id" IS '流程定义 ID';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."node_code" IS '节点编码';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."node_name" IS '节点名称（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."node_type" IS '节点类型（FlowNodeType.code）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."business_type" IS '业务类型';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."business_id" IS '业务单据 ID';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."business_no" IS '业务单据编号';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."flow_name" IS '流程名称（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."title" IS '任务标题';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."assignee_type" IS '办理人类型（FlowAssigneeType 枚举名）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."assignee_id" IS '办理人 ID';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."assignee_name" IS '办理人姓名（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."perform_type" IS '会签类型（FlowPerformType 枚举名）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."approve_count" IS '会签所需通过人数';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."approve_finished" IS '会签当前已通过人数';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."vote_pass_rate" IS '通过率阈值（0~1，从源 task 复制）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."task_status" IS '任务状态（终态：APPROVED/REJECTED/CANCELED/DELEGATED）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."comment" IS '审批意见（终态时填写）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."claim_at" IS '签收时间';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."finish_at" IS '完成时间（终态时刻）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."effective_time" IS '生效时间（P2-1 穿越时空/补录审批，从源 task 复制，NULL=即时生效）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."duration_ms" IS '耗时（毫秒）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."provider_trace_id" IS '链路追踪 ID（保留原始 trace 便于历史回溯）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."iter_var" IS 'FOREACH 迭代元素值（从源 task 复制，非循环节点为 NULL）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_flow_his_task"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_flow_his_task_assignee_id" ON "public"."ydsz_flow_his_task" USING btree ("assignee_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_his_task_assignee_operated" ON "public"."ydsz_flow_his_task" USING btree ("tenant_id" ASC NULLS LAST, "assignee_id" ASC NULLS LAST, "finish_at" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_flow_his_task_business" ON "public"."ydsz_flow_his_task" USING btree ("business_type" ASC NULLS LAST, "business_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_his_task_finish_at" ON "public"."ydsz_flow_his_task" USING btree ("finish_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_his_task_instance_id" ON "public"."ydsz_flow_his_task" USING btree ("instance_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_his_task_tenant_is_deleted" ON "public"."ydsz_flow_his_task" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_flow_idempotent" CASCADE;

CREATE TABLE "public"."ydsz_flow_idempotent" (
                                                 "id" character varying(36) NOT NULL,
                                                 "scope" character varying(64) NOT NULL,
                                                 "key_hash" character varying(64) NOT NULL,
                                                 "key_raw" character varying(512) DEFAULT NULL::character varying,
                                                 "result_data" text,
                                                 "status" character varying(16) NOT NULL DEFAULT 'PROCESSING'::character varying,
                                                 "retry_count" integer NOT NULL DEFAULT 0,
                                                 "error_message" character varying(512) DEFAULT NULL::character varying,
                                                 "ttl_at" timestamp without time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP + '7 days'::interval),
                                                 "sort" integer DEFAULT 0,
                                                 "revision" integer DEFAULT 0,
                                                 "tenant_id" character varying(36) DEFAULT '0'::character varying,
                                                 "is_deleted" smallint NOT NULL DEFAULT 0,
                                                 "created_by" character varying(36) DEFAULT NULL::character varying,
                                                 "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                 "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                 "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                 CONSTRAINT "ydsz_flow_idempotent_pkey" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_flow_idempotent" IS '工作流全链路幂等记录表';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."scope" IS '幂等作用域（如 workflow.advance / workflow.start / workflow.reject）';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."key_hash" IS '幂等键哈希（SHA-256），唯一约束';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."key_raw" IS '幂等键明文（便于排查）';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."result_data" IS '成功结果 JSON（供重复请求直接返回）';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."status" IS '处理状态（PROCESSING / SUCCESS / FAILED）';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."retry_count" IS '重试次数';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."error_message" IS '最后一次错误信息';
COMMENT ON COLUMN "public"."ydsz_flow_idempotent"."ttl_at" IS '过期时间（自动清理依据）';
CREATE INDEX "idx_ydsz_flow_idempotent_tenant_status" ON "public"."ydsz_flow_idempotent" USING btree ("tenant_id" ASC NULLS LAST, "status" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_idempotent_ttl_at" ON "public"."ydsz_flow_idempotent" USING btree ("ttl_at" ASC NULLS LAST) WHERE ((status)::text = 'SUCCESS'::text);
CREATE UNIQUE INDEX "uk_ydsz_flow_idempotent_scope_hash" ON "public"."ydsz_flow_idempotent" USING btree ("scope" ASC NULLS LAST, "key_hash" ASC NULLS LAST) WHERE ((status)::text = ANY ((ARRAY['PROCESSING'::character varying, 'SUCCESS'::character varying])::text[]));

DROP TABLE IF EXISTS "public"."ydsz_flow_instance" CASCADE;

CREATE TABLE "public"."ydsz_flow_instance" (
                                               "id" character varying(36) NOT NULL,
                                               "flow_code" character varying(64) NOT NULL,
                                               "flow_name" character varying(128) NOT NULL,
                                               "definition_id" character varying(36) NOT NULL,
                                               "flow_version" character varying(32) NOT NULL,
                                               "business_type" character varying(64) NOT NULL,
                                               "business_id" character varying(36) NOT NULL,
                                               "business_no" character varying(64) DEFAULT NULL::character varying,
                                               "title" character varying(128) DEFAULT NULL::character varying,
                                               "initiator_id" character varying(36) NOT NULL,
                                               "initiator_name" character varying(64) DEFAULT NULL::character varying,
                                               "current_node_code" character varying(64) DEFAULT NULL::character varying,
                                               "current_node_name" character varying(128) DEFAULT NULL::character varying,
                                               "variable" jsonb,
                                               "flow_status" character varying(32) NOT NULL,
                                               "activity_status" integer NOT NULL DEFAULT 1,
                                               "start_at" timestamp without time zone,
                                               "end_at" timestamp without time zone,
                                               "duration_ms" bigint,
                                               "parent_instance_id" character varying(36) DEFAULT NULL::character varying,
                                               "parent_node_code" character varying(64) DEFAULT NULL::character varying,
                                               "provider_trace_id" character varying(36) DEFAULT NULL::character varying,
                                               "due_at" timestamp without time zone,
                                               "reject_reason" character varying(512) DEFAULT NULL::character varying,
                                               "status" character varying(32) DEFAULT NULL::character varying,
                                               "sort" integer DEFAULT 0,
                                               "revision" integer NOT NULL DEFAULT 0,
                                               "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                               "is_deleted" smallint NOT NULL DEFAULT 0,
                                               "created_by" character varying(36) DEFAULT NULL::character varying,
                                               "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                               "updated_by" character varying(36) DEFAULT NULL::character varying,
                                               "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                               CONSTRAINT "pk_ydsz_flow_instance" PRIMARY KEY (id),
                                               CONSTRAINT "uk_ydsz_flow_instance_business_type_id" UNIQUE (business_type, business_id)
);
COMMENT ON TABLE "public"."ydsz_flow_instance" IS '流程实例表（一次完整流程审批的运行时上下文）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."flow_code" IS '流程编码（业务侧使用，如 project_initiation）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."flow_name" IS '流程名称（冗余，避免 JOIN 流程定义）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."definition_id" IS '流程定义 ID（关联 ydsz_flow_definition.id）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."flow_version" IS '流程版本（关联 ydsz_flow_definition.flow_version）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."business_type" IS '业务类型（如 PROJECT / CONTRACT / LEAVE）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."business_id" IS '业务单据 ID（业务侧主键）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."business_no" IS '业务单据编号（业务侧编号，可读）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."title" IS '流程标题（展示用，默认为「{业务类型}-{业务编号}」）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."initiator_id" IS '发起人 ID（关联 ydsz_user_account.id）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."initiator_name" IS '发起人姓名（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."current_node_code" IS '当前节点编码（流程图高亮 + 进度提示）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."current_node_name" IS '当前节点名称（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."variable" IS '流程变量 JSON（动态参数）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."flow_status" IS '实例状态（FlowInstanceStatus 枚举名，如 RUNNING/APPROVED/REJECTED）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."activity_status" IS '激活状态（0=挂起，1=激活，与 flowStatus 解耦）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."start_at" IS '启动时间';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."end_at" IS '结束时间（终态实例有值，活跃实例为 NULL）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."duration_ms" IS '流程耗时（毫秒，endAt - startAt，结束时由引擎填充）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."parent_instance_id" IS '父流程实例 ID（子流程场景，可空）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."parent_node_code" IS '父流程中触发子流程的节点编码（可空）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."provider_trace_id" IS '链路追踪 ID（关联 MDC traceId，用于跨服务追踪）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."due_at" IS '子流程超时时间（超时自动终止子流程，可空）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."reject_reason" IS '退回原因（最近一次 REJECT 操作的备注，重审时清空）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_flow_instance"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_flow_instance_flow_status" ON "public"."ydsz_flow_instance" USING btree ("flow_status" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_instance_initiator_id" ON "public"."ydsz_flow_instance" USING btree ("initiator_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_instance_status_def_end" ON "public"."ydsz_flow_instance" USING btree ("tenant_id" ASC NULLS LAST, "status" ASC NULLS LAST, "definition_id" ASC NULLS LAST, "end_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_instance_tenant_flow_code_time" ON "public"."ydsz_flow_instance" USING btree ("tenant_id" ASC NULLS LAST, "flow_code" ASC NULLS LAST, "created_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_instance_tenant_is_deleted" ON "public"."ydsz_flow_instance" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_flow_node" CASCADE;

CREATE TABLE "public"."ydsz_flow_node" (
                                           "id" character varying(36) NOT NULL,
                                           "definition_id" character varying(36) NOT NULL,
                                           "flow_code" character varying(64) NOT NULL,
                                           "node_type" integer NOT NULL,
                                           "node_code" character varying(64) NOT NULL,
                                           "node_name" character varying(128) NOT NULL,
                                           "permission_flag" character varying(512) DEFAULT NULL::character varying,
                                           "skip_any_node" character varying(512) DEFAULT NULL::character varying,
                                           "coordinate" jsonb,
                                           "skip_list" jsonb,
                                           "ext" jsonb,
                                           "form_fields_config" jsonb,
                                           "sla_config" jsonb,
                                           "provider_trace_id" character varying(36) DEFAULT NULL::character varying,
                                           "status" character varying(32) DEFAULT NULL::character varying,
                                           "sort" integer DEFAULT 0,
                                           "revision" integer NOT NULL DEFAULT 0,
                                           "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                           "is_deleted" smallint NOT NULL DEFAULT 0,
                                           "created_by" character varying(36) DEFAULT NULL::character varying,
                                           "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                           "updated_by" character varying(36) DEFAULT NULL::character varying,
                                           "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                           CONSTRAINT "pk_ydsz_flow_node" PRIMARY KEY (id),
                                           CONSTRAINT "uk_ydsz_flow_node_definition_node_code" UNIQUE (definition_id, node_code)
);
COMMENT ON TABLE "public"."ydsz_flow_node" IS '流程节点表（流程定义结构最小单元）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."definition_id" IS '所属流程定义 ID（关联 ydsz_flow_definition.id）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."flow_code" IS '流程编码（冗余字段，避免 JOIN 流程定义）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."node_type" IS '节点类型（0=开始，1=审批，2=网关，3=结束，4=子流程，5=抄送）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."node_code" IS '节点编码（流程内唯一，用于 SpEL 引用与跳转）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."node_name" IS '节点名称（设计器展示与审批页标题）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."permission_flag" IS '办理人权限标识（role:/dept:/user:/post:/initiator/initiatorLeader/，逗号分隔）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."skip_any_node" IS '任意跳转目标节点编码集合（逗号分隔，空=不允许任意跳转）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."coordinate" IS '设计器坐标 JSON（{"x":100,"y":200,"width":120,"height":60}，bpmn-js 生成）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."skip_list" IS '节点跳转路由集合 JSON（[{toNodeCode,condition,priority},...]，按优先级匹配）';
COMMENT ON COLUMN "public"."ydsz_flow_node"."ext" IS '扩展字段 JSON（priority/emptyStrategy/collection/votePassRate/userWeights/autoDedup/freeJump）';
