COMMENT ON COLUMN "public"."ydsz_flow_node"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_flow_node"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_flow_node"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_flow_node_flow_code" ON "public"."ydsz_flow_node" USING btree ("flow_code" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_node_tenant_is_deleted" ON "public"."ydsz_flow_node" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

