DROP TABLE IF EXISTS "public"."ydsz_flow_run_task" CASCADE;

CREATE TABLE "public"."ydsz_flow_run_task" (
                                               "id" character varying(36) NOT NULL,
                                               "instance_id" character varying(36) NOT NULL,
                                               "flow_code" character varying(64) NOT NULL,
                                               "definition_id" character varying(36) NOT NULL,
                                               "node_code" character varying(64) NOT NULL,
                                               "node_name" character varying(128) DEFAULT NULL::character varying,
                                               "node_type" integer,
                                               "business_type" character varying(64) DEFAULT NULL::character varying,
                                               "business_id" character varying(36) DEFAULT NULL::character varying,
                                               "business_no" character varying(64) DEFAULT NULL::character varying,
                                               "flow_name" character varying(128) DEFAULT NULL::character varying,
                                               "title" character varying(128) DEFAULT NULL::character varying,
                                               "assignor_id" character varying(36) DEFAULT NULL::character varying,
                                               "assignor_name" character varying(64) DEFAULT NULL::character varying,
                                               "assignee_type" character varying(32) DEFAULT NULL::character varying,
                                               "assignee_id" character varying(36) NOT NULL,
                                               "assignee_name" character varying(64) DEFAULT NULL::character varying,
                                               "permission_flag" character varying(512) DEFAULT NULL::character varying,
                                               "perform_type" character varying(32) DEFAULT NULL::character varying,
                                               "approve_count" integer,
                                               "approve_finished" integer,
                                               "vote_pass_rate" numeric(20,6) DEFAULT NULL::numeric,
                                               "user_weight" integer,
                                               "approve_weight" integer,
                                               "total_weight" integer,
                                               "task_status" character varying(32) NOT NULL,
                                               "comment" character varying(512) DEFAULT NULL::character varying,
                                               "claim_at" timestamp without time zone,
                                               "finish_at" timestamp without time zone,
                                               "effective_time" timestamp without time zone,
                                               "duration_ms" bigint,
                                               "due_at" timestamp without time zone,
                                               "priority" integer NOT NULL DEFAULT 50,
                                               "urge_count" integer NOT NULL DEFAULT 0,
                                               "last_urged_at" timestamp without time zone,
                                               "sla_action" character varying(32) DEFAULT NULL::character varying,
                                               "sla_escalated" integer NOT NULL DEFAULT 0,
                                               "iter_var" character varying(128) NOT NULL DEFAULT ''::character varying,
                                               "provider_trace_id" character varying(36) DEFAULT NULL::character varying,
                                               "status" character varying(32) DEFAULT NULL::character varying,
                                               "sort" integer DEFAULT 0,
                                               "revision" integer NOT NULL DEFAULT 0,
                                               "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                               "is_deleted" smallint NOT NULL DEFAULT 0,
                                               "created_by" character varying(36) DEFAULT NULL::character varying,
                                               "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                               "updated_by" character varying(36) DEFAULT NULL::character varying,
                                               "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                               CONSTRAINT "pk_ydsz_flow_run_task" PRIMARY KEY (id),
                                               CONSTRAINT "uk_ydsz_flow_run_task_instance_node_assignee" UNIQUE (instance_id, node_code, assignee_id, iter_var)
);
COMMENT ON TABLE "public"."ydsz_flow_run_task" IS '待办任务运行表（我的待办核心查询表）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."instance_id" IS '流程实例 ID（关联 ydsz_flow_instance.id）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."flow_code" IS '流程编码（冗余字段）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."definition_id" IS '流程定义 ID';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."node_code" IS '节点编码';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."node_name" IS '节点名称（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."node_type" IS '节点类型（FlowNodeType.code）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."business_type" IS '业务类型';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."business_id" IS '业务单据 ID';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."business_no" IS '业务单据编号';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."flow_name" IS '流程名称（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."title" IS '任务标题（默认为「{流程名}-{节点名}-{业务编号}」）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."assignor_id" IS '委托人 ID（委托操作产生，被委托人完成任务后回填）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."assignor_name" IS '委托人姓名（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."assignee_type" IS '办理人类型（FlowAssigneeType 枚举名：USER/ROLE/DEPT/POST）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."assignee_id" IS '办理人 ID（按 type 解析，USER 传 userId，ROLE 传 roleCode）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."assignee_name" IS '办理人姓名（冗余）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."permission_flag" IS '办理人权限标识（原始 SpEL 表达式，存档便于回溯）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."perform_type" IS '会签类型（FlowPerformType 枚举名：OR=或签，PARALLEL=并行会签，WEIGHTED=票签）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."approve_count" IS '会签所需通过人数（PARALLEL 模式：会签总人数）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."approve_finished" IS '会签当前已通过人数';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."vote_pass_rate" IS '通过率阈值（0~1，默认 0.5 表示过半数）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."user_weight" IS '当前办理人的权重值（票签模式，未配置默认 1）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."approve_weight" IS '累计已通过权重（票签模式：每次通过时累加 userWeight）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."total_weight" IS '节点总权重（票签模式：所有办理人权重之和）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."task_status" IS '任务状态（FlowTaskStatus 枚举名）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."comment" IS '审批意见';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."claim_at" IS '签收时间（多人会签时记录每个办理人的签收时间）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."finish_at" IS '完成时间';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."duration_ms" IS '耗时（毫秒，finishAt - claimAt）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."due_at" IS '截止时间（SLA 阈值，由 slaConfig.timeoutMinutes 计算）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."priority" IS '任务优先级（1-100，默认 50，待办按 priority DESC, created_at ASC 排序）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."urge_count" IS '已发送的 SLA 催办次数（超过配置上限后停止）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."last_urged_at" IS '最近一次催办时间';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."sla_action" IS '最终触发的 SLA 动作（REMIND/ESCALATE/AUTO_PASS/AUTO_REJECT）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."sla_escalated" IS '是否已升级（0=否，1=是，避免重复升级）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."iter_var" IS 'FOREACH 节点当前迭代元素值（如 userId/deptId，非循环节点为空字符串占位，保证唯一约束幂等生效）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."provider_trace_id" IS '链路追踪 ID';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_flow_run_task"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_flow_run_task_assignee_id" ON "public"."ydsz_flow_run_task" USING btree ("assignee_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_run_task_assignee_status_due" ON "public"."ydsz_flow_run_task" USING btree ("tenant_id" ASC NULLS LAST, "assignee_id" ASC NULLS LAST, "status" ASC NULLS LAST, "due_at" DESC NULLS FIRST, "created_at" DESC NULLS FIRST);
CREATE INDEX "idx_ydsz_flow_run_task_assignee_status_is_deleted" ON "public"."ydsz_flow_run_task" USING btree ("assignee_id" ASC NULLS LAST, "status" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_run_task_business" ON "public"."ydsz_flow_run_task" USING btree ("business_type" ASC NULLS LAST, "business_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_run_task_due_at" ON "public"."ydsz_flow_run_task" USING btree ("due_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_run_task_tenant_is_deleted" ON "public"."ydsz_flow_run_task" USING btree ("tenant_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_flow_skip" CASCADE;

CREATE TABLE "public"."ydsz_flow_skip" (
                                           "id" character varying(36) NOT NULL,
                                           "definition_id" character varying(36) NOT NULL,
                                           "flow_code" character varying(64) NOT NULL,
                                           "skip_name" character varying(128) DEFAULT NULL::character varying,
                                           "skip_type" character varying(32) NOT NULL,
                                           "coordinate" jsonb,
