COMMENT ON COLUMN "public"."ydsz_flow_skip"."skip_list" IS '跳转路由集合 JSON';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."ext" IS '扩展字段 JSON（存储 sourceRef / sequenceFlowId 等 BPMN 派生信息）';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."provider_trace_id" IS '链路追踪 ID';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."status" IS '状态标识';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_flow_skip"."updated_at" IS '最后更新时间';
CREATE INDEX "idx_ydsz_flow_skip_definition_id" ON "public"."ydsz_flow_skip" USING btree ("definition_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_skip_flow_code" ON "public"."ydsz_flow_skip" USING btree ("flow_code" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_flow_skip_source_node_code" ON "public"."ydsz_flow_skip" USING btree ("source_node_code" ASC NULLS LAST);
