COMMENT ON TABLE "public"."ydsz_flow_template" IS '流程模板表（模板市场预置模板，BPMN 2.0 XML）';
COMMENT ON COLUMN "public"."ydsz_flow_template"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_flow_template"."template_code" IS '模板编码（唯一标识，如 hr_leave_approval）';
COMMENT ON COLUMN "public"."ydsz_flow_template"."template_name" IS '模板名称（前端展示）';
COMMENT ON COLUMN "public"."ydsz_flow_template"."category" IS '分类（HR / FINANCE / ADMIN / PROJECT / GENERAL）';
COMMENT ON COLUMN "public"."ydsz_flow_template"."description" IS '模板描述（说明适用场景、必填字段、注意事项）';
COMMENT ON COLUMN "public"."ydsz_flow_template"."icon" IS '图标路径（前端展示用）';
COMMENT ON COLUMN "public"."ydsz_flow_template"."bpmn_xml" IS 'BPMN 2.0 XML 流程定义（<bpmn:definitions>...</bpmn:definitions>）';
