COMMENT ON COLUMN "public"."ydsz_idm_menu"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_idm_menu"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_idm_menu"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_idm_menu"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_idm_menu"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_idm_menu"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_idm_menu"."updated_at" IS '最后更新时间';
