DROP TABLE IF EXISTS "public"."ydsz_job_alert_dispatch" CASCADE;

CREATE TABLE "public"."ydsz_job_alert_dispatch" (
                                                    "id" character varying(36) NOT NULL,
                                                    "alert_code" character varying(64) NOT NULL,
                                                    "source_type" character varying(32) NOT NULL,
                                                    "rule_id" character varying(36) DEFAULT NULL::character varying,
                                                    "rule_name" character varying(128) DEFAULT NULL::character varying,
                                                    "job_id" character varying(36) DEFAULT NULL::character varying,
                                                    "job_key" character varying(64) DEFAULT NULL::character varying,
                                                    "alert_type" character varying(32) DEFAULT NULL::character varying,
                                                    "alert_level" character varying(32) DEFAULT NULL::character varying,
                                                    "trigger_value" character varying(64) DEFAULT NULL::character varying,
                                                    "threshold" bigint,
                                                    "channels" character varying(256) DEFAULT NULL::character varying,
                                                    "alert_status" character varying(32) DEFAULT NULL::character varying,
                                                    "error_message" text,
                                                    "trace_id" character varying(36) DEFAULT NULL::character varying,
                                                    "trigger_log_id" character varying(36) DEFAULT NULL::character varying,
                                                    "sort" integer DEFAULT 0,
                                                    "status" integer DEFAULT 1,
                                                    "revision" integer DEFAULT 0,
                                                    "tenant_id" character varying(36) DEFAULT '1'::character varying,
                                                    "is_deleted" smallint NOT NULL DEFAULT 0,
                                                    "created_by" character varying(36) DEFAULT NULL::character varying,
                                                    "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                    "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                    "updated_at" timestamp without time zone DEFAULT now(),
                                                    CONSTRAINT "pk_ydsz_job_alert_dispatch" PRIMARY KEY (id),
                                                    CONSTRAINT "uk_ydsz_job_alert_dispatch_ad_alert_code" UNIQUE (alert_code)
);
COMMENT ON TABLE "public"."ydsz_job_alert_dispatch" IS '告警派发日志表（cronjob 告警记录，source_type=CRONJOB）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."alert_code" IS '预警编码（cronjob 自动生成: CRONJOB-{timestamp}-{ruleId}）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."source_type" IS '触发源类型（cronjob 告警固定为 CRONJOB）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."rule_id" IS '规则 ID（映射到 rule_id）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."rule_name" IS '规则名称（映射到 title）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."job_id" IS '任务 ID（NULL 表示全局告警; 映射到 source_id）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."job_key" IS '任务 KEY（冗余）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."alert_type" IS '告警类型: FAIL / TIMEOUT / SLOW / FAIL_RATE / DURATION_P95';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."alert_level" IS '告警级别: INFO / WARN / ERROR / CRITICAL';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."trigger_value" IS '触发时的实际值（如失败率 85.5、耗时 5000）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."threshold" IS '规则阈值（冗余）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."channels" IS '实际发送通道（逗号分隔: INAPP,EMAIL,DINGTALK）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."alert_status" IS '告警状态: PENDING / SUCCESS / PARTIAL / FAILED / *_RECOVERY';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."error_message" IS '错误信息（部分通道失败时记录; 映射到 fail_reason）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."trace_id" IS '链路追踪 ID（映射到 provider_trace_id）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."trigger_log_id" IS '触发该告警的任务日志 ID（关联 ydsz_job_log.id）';
COMMENT ON COLUMN "public"."ydsz_job_alert_dispatch"."created_at" IS '创建时间';
CREATE INDEX "idx_ydsz_job_alert_dispatch_ad_job_id" ON "public"."ydsz_job_alert_dispatch" USING btree ("job_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_job_alert_dispatch_ad_rule_id" ON "public"."ydsz_job_alert_dispatch" USING btree ("rule_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_job_alert_dispatch_ad_source_status" ON "public"."ydsz_job_alert_dispatch" USING btree ("source_type" ASC NULLS LAST, "alert_status" ASC NULLS LAST);

