DROP TABLE IF EXISTS "public"."ydsz_job_log" CASCADE;

CREATE TABLE "public"."ydsz_job_log" (
                                         "id" character varying(36) NOT NULL,
                                         "job_id" character varying(36) NOT NULL,
                                         "job_key" character varying(64) NOT NULL,
