                                         "end_time" timestamp without time zone,
                                         "duration_ms" bigint,
                                         "error_message" text,
                                         "params_json" jsonb,
                                         "result_json" jsonb,
                                         "trace_id" character varying(36) DEFAULT NULL::character varying,
                                         "trigger_type" character varying(32) DEFAULT NULL::character varying,
                                         "lock_holder" character varying(64) DEFAULT NULL::character varying,
                                         "exec_node_id" character varying(36) DEFAULT NULL::character varying,
                                         "exec_thread_id" bigint,
                                         "shard_index" integer,
                                         "shard_total" integer,
                                         "slow" smallint NOT NULL DEFAULT 0,
                                         "slow_threshold_ms" bigint,
                                         "queue_time" timestamp without time zone,
                                         "dispatch_time" timestamp without time zone,
                                         "handler_init_time" timestamp without time zone,
                                         "handler_end_time" timestamp without time zone,
                                         "status" character varying(32) DEFAULT NULL::character varying,
                                         "sort" integer DEFAULT 0,
                                         "revision" integer DEFAULT 0,
                                         "tenant_id" character varying(36) DEFAULT '1'::character varying,
                                         "is_deleted" smallint NOT NULL DEFAULT 0,
                                         "created_by" character varying(36) DEFAULT NULL::character varying,
                                         "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                         "updated_by" character varying(36) DEFAULT NULL::character varying,
                                         "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                         CONSTRAINT "pk_ydsz_job_log" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_job_log" IS '任务执行日志表';
COMMENT ON COLUMN "public"."ydsz_job_log"."id" IS '主键 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_job_log"."job_id" IS '任务 ID';
COMMENT ON COLUMN "public"."ydsz_job_log"."job_key" IS '任务 KEY';
COMMENT ON COLUMN "public"."ydsz_job_log"."start_time" IS '开始时间';
COMMENT ON COLUMN "public"."ydsz_job_log"."end_time" IS '结束时间';
COMMENT ON COLUMN "public"."ydsz_job_log"."duration_ms" IS '耗时(毫秒)';
COMMENT ON COLUMN "public"."ydsz_job_log"."error_message" IS '错误信息';
COMMENT ON COLUMN "public"."ydsz_job_log"."params_json" IS '参数 JSON';
COMMENT ON COLUMN "public"."ydsz_job_log"."result_json" IS '结果 JSON';
COMMENT ON COLUMN "public"."ydsz_job_log"."trace_id" IS '链路追踪 ID';
