COMMENT ON COLUMN "public"."ydsz_job_log"."shard_total" IS '分片总数（非分片任务为 NULL）';
COMMENT ON COLUMN "public"."ydsz_job_log"."slow" IS '慢任务标记（0=非慢 / 1=慢）';
COMMENT ON COLUMN "public"."ydsz_job_log"."slow_threshold_ms" IS '慢任务阈值快照（毫秒，NULL=未配置慢任务检测）';
