COMMENT ON COLUMN "public"."ydsz_job_log"."dispatch_time" IS '派发时间（任务被 Dispatcher 从队列取出并派发的时刻）';
COMMENT ON COLUMN "public"."ydsz_job_log"."handler_init_time" IS 'Handler 初始化时间（JobHandler 实例化/资源准备完成的时刻）';
COMMENT ON COLUMN "public"."ydsz_job_log"."handler_end_time" IS 'Handler 执行结束时间（JobHandler.execute() 返回的时刻）';
COMMENT ON COLUMN "public"."ydsz_job_log"."status" IS '执行状态: RUNNING/SUCCESS/FAILED/TIMEOUT';
COMMENT ON COLUMN "public"."ydsz_job_log"."is_deleted" IS '逻辑删除标识：0=未删除，1=已删除';
COMMENT ON COLUMN "public"."ydsz_job_log"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_job_log"."updated_at" IS '更新时间';
CREATE INDEX "idx_ydsz_job_log_jl_job_id" ON "public"."ydsz_job_log" USING btree ("job_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_job_log_jl_job_key" ON "public"."ydsz_job_log" USING btree ("job_key" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_job_log_jl_start_time" ON "public"."ydsz_job_log" USING btree ("start_time" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_job_log_jl_status" ON "public"."ydsz_job_log" USING btree ("status" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_job_log_jl_trace_id" ON "public"."ydsz_job_log" USING btree ("trace_id" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_job_log_job_key_status_created" ON "public"."ydsz_job_log" USING btree ("job_key" ASC NULLS LAST, "status" ASC NULLS LAST, "created_at" ASC NULLS LAST);

