COMMENT ON COLUMN "public"."ydsz_msg_template"."description" IS '描述说明';
COMMENT ON COLUMN "public"."ydsz_msg_template"."variable_defs" IS '模板变量定义（JSON）';
COMMENT ON COLUMN "public"."ydsz_msg_template"."tenant_id" IS '租户 ID（多租户隔离）';
COMMENT ON COLUMN "public"."ydsz_msg_template"."is_deleted" IS '逻辑删除标识（0=未删除，1=已删除）';
COMMENT ON COLUMN "public"."ydsz_msg_template"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_msg_template"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_msg_template"."updated_by" IS '最后更新人';
COMMENT ON COLUMN "public"."ydsz_msg_template"."updated_at" IS '最后更新时间';
