                                           CONSTRAINT "pk_ydsz_msg_trace" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_msg_trace" IS '消息轨迹表';
COMMENT ON COLUMN "public"."ydsz_msg_trace"."id" IS '主键 ID（Snowflake）';
