COMMENT ON COLUMN "public"."ydsz_msg_trace"."status" IS '节点状态: SUCCESS / FAILED / SKIPPED / PENDING';
COMMENT ON COLUMN "public"."ydsz_msg_trace"."channel" IS '通道（节点关联的通道，部分节点如 RECEIVED 无通道则为 NULL）';
