COMMENT ON COLUMN "public"."ydsz_msg_trace"."biz_type" IS '业务类型';
COMMENT ON COLUMN "public"."ydsz_msg_trace"."biz_id" IS '业务单据 ID';
COMMENT ON COLUMN "public"."ydsz_msg_trace"."template_code" IS '模板编码';
COMMENT ON COLUMN "public"."ydsz_msg_trace"."cost_ms" IS '节点耗时（毫秒）';
COMMENT ON COLUMN "public"."ydsz_msg_trace"."message" IS '节点描述 / 错误信息';
COMMENT ON COLUMN "public"."ydsz_msg_trace"."extra" IS '扩展信息（JSON，如路由规则 ID、降级链、灰度配置等）';
COMMENT ON COLUMN "public"."ydsz_msg_trace"."event_at" IS '节点发生时间';
CREATE INDEX "idx_ydsz_msg_trace_event_at" ON "public"."ydsz_msg_trace" USING btree ("event_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_msg_trace_msg_event" ON "public"."ydsz_msg_trace" USING btree ("msg_id" ASC NULLS LAST, "event_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_msg_trace_node_status" ON "public"."ydsz_msg_trace" USING btree ("node" ASC NULLS LAST, "status" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_msg_trace_trace_id" ON "public"."ydsz_msg_trace" USING btree ("trace_id" ASC NULLS LAST);

