DROP TABLE IF EXISTS "public"."ydsz_system_config_approval" CASCADE;

CREATE TABLE "public"."ydsz_system_config_approval" (
                                                        "id" character varying(36) NOT NULL,
                                                        "resource_type" character varying(32) NOT NULL,
                                                        "resource_key" character varying(128) NOT NULL,
                                                        "resource_group" character varying(128) DEFAULT NULL::character varying,
                                                        "change_type" character varying(16) NOT NULL,
                                                        "before_json" text,
                                                        "after_json" text,
                                                        "status" character varying(16) NOT NULL DEFAULT 'PENDING'::character varying,
                                                        "submitter_id" character varying(36) DEFAULT NULL::character varying,
                                                        "submitted_at" timestamp without time zone,
                                                        "reason" character varying(512) DEFAULT NULL::character varying,
                                                        "rejection_reason" character varying(512) DEFAULT NULL::character varying,
                                                        "closed_at" timestamp without time zone,
                                                        "sort" integer DEFAULT 0,
                                                        "revision" integer NOT NULL DEFAULT 0,
                                                        "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                                        "is_deleted" smallint NOT NULL DEFAULT 0,
                                                        "created_by" character varying(36) DEFAULT NULL::character varying,
                                                        "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                        "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                        "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                        CONSTRAINT "pk_ydsz_system_config_approval" PRIMARY KEY (id),
                                                        CONSTRAINT "uk_ydsz_system_config_approval_resource" UNIQUE (tenant_id, resource_type, resource_key, status)
);
COMMENT ON TABLE "public"."ydsz_system_config_approval" IS '配置变更审批单（CONFIG / DICT / VARIABLE 三类资源的审批流记录）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."id" IS '审批单唯一 ID（Snowflake）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."resource_type" IS '资源类型（CONFIG / DICT / VARIABLE）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."resource_key" IS '资源唯一标识';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."resource_group" IS '资源分组（仅 CONFIG 类型有值）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."change_type" IS '变更操作类型（CREATE / UPDATE / DELETE）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."before_json" IS '变更前的 JSON 值（CREATE 时为空）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."after_json" IS '变更后的 JSON 值（DELETE 时为空）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."status" IS '审批状态（PENDING / APPROVED / REJECTED / WITHDRAWN）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."submitter_id" IS '发起人 ID';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."submitted_at" IS '发起时间';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."reason" IS '变更原因';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."rejection_reason" IS '拒绝原因（REJECTED 时有值）';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."closed_at" IS '审批单关闭时间';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."revision" IS '乐观锁版本号';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."tenant_id" IS '租户 ID';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."is_deleted" IS '逻辑删除: 0=未删除, 1=已删除';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."created_by" IS '创建人';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."updated_by" IS '更新人';
COMMENT ON COLUMN "public"."ydsz_system_config_approval"."updated_at" IS '更新时间';
CREATE INDEX "idx_ydsz_system_config_approval_submitter" ON "public"."ydsz_system_config_approval" USING btree ("submitter_id" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_system_config_approval_tenant_status" ON "public"."ydsz_system_config_approval" USING btree ("tenant_id" ASC NULLS LAST, "status" ASC NULLS LAST, "is_deleted" ASC NULLS LAST);

