COMMENT ON COLUMN "public"."ydsz_gen_table_meta"."id" IS '主键 ID';
COMMENT ON COLUMN "public"."ydsz_gen_table_meta"."datasource_id" IS '关联数据源 ID';
COMMENT ON COLUMN "public"."ydsz_gen_table_meta"."table_name" IS '物理表名';
COMMENT ON COLUMN "public"."ydsz_gen_table_meta"."comment" IS '表注释';
COMMENT ON COLUMN "public"."ydsz_gen_table_meta"."alias_name" IS '用户自定义别名（用于类名生成）';
COMMENT ON COLUMN "public"."ydsz_gen_table_meta"."module_name" IS '模块名称（用于包路径）';
COMMENT ON COLUMN "public"."ydsz_gen_table_meta"."cached_at" IS '缓存时间';
COMMENT ON COLUMN "public"."ydsz_gen_table_meta"."created_at" IS '创建时间';
CREATE INDEX "idx_ydsz_gen_table_meta_datasource" ON "public"."ydsz_gen_table_meta" USING btree ("datasource_id" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_gen_history" CASCADE;

CREATE TABLE "public"."ydsz_gen_history" (
                                             "id" character varying(36) NOT NULL,
                                             "module_name" character varying(64) NOT NULL,
                                             "datasource_id" character varying(36) NOT NULL,
                                             "template_group_id" character varying(36) NOT NULL,
                                             "table_count" integer NOT NULL DEFAULT 0,
                                             "file_count" integer NOT NULL DEFAULT 0,
                                             "status" character varying(16) NOT NULL DEFAULT 'RUNNING'::character varying,
                                             "triggered_by" character varying(64) DEFAULT NULL::character varying,
                                             "started_at" timestamp without time zone NOT NULL,
                                             "finished_at" timestamp without time zone,
                                             "error_message" text,
                                             "gen_params" jsonb,
                                             "sort" integer DEFAULT 0,
                                             "revision" integer DEFAULT 0,
                                             "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                             "is_deleted" smallint NOT NULL DEFAULT 0,
                                             "created_by" character varying(36) DEFAULT NULL::character varying,
                                             "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                             "updated_by" character varying(36) DEFAULT NULL::character varying,
                                             "updated_at" timestamp without time zone DEFAULT now(),
                                             CONSTRAINT "pk_ydsz_gen_history" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_gen_history" IS '代码生成任务历史';
COMMENT ON COLUMN "public"."ydsz_gen_history"."id" IS '主键 ID';
COMMENT ON COLUMN "public"."ydsz_gen_history"."module_name" IS '模块名称';
COMMENT ON COLUMN "public"."ydsz_gen_history"."datasource_id" IS '使用的数据源 ID';
COMMENT ON COLUMN "public"."ydsz_gen_history"."template_group_id" IS '使用的模板分组 ID';
COMMENT ON COLUMN "public"."ydsz_gen_history"."table_count" IS '涉及表数量';
COMMENT ON COLUMN "public"."ydsz_gen_history"."file_count" IS '生成文件总数';
COMMENT ON COLUMN "public"."ydsz_gen_history"."status" IS '执行状态（RUNNING/SUCCESS/PARTIAL/FAILED）';
COMMENT ON COLUMN "public"."ydsz_gen_history"."triggered_by" IS '触发人（用户名）';
COMMENT ON COLUMN "public"."ydsz_gen_history"."started_at" IS '开始时间';
COMMENT ON COLUMN "public"."ydsz_gen_history"."finished_at" IS '完成时间';
COMMENT ON COLUMN "public"."ydsz_gen_history"."error_message" IS '错误信息（失败时记录）';
COMMENT ON COLUMN "public"."ydsz_gen_history"."gen_params" IS '生成参数 JSON 快照';
COMMENT ON COLUMN "public"."ydsz_gen_history"."created_at" IS '创建时间';
CREATE INDEX "idx_ydsz_gen_history_started" ON "public"."ydsz_gen_history" USING btree ("started_at" ASC NULLS LAST);
CREATE INDEX "idx_ydsz_gen_history_status" ON "public"."ydsz_gen_history" USING btree ("status" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_gen_template" CASCADE;

CREATE TABLE "public"."ydsz_gen_template" (
                                              "id" character varying(36) NOT NULL,
                                              "group_id" character varying(36) NOT NULL,
                                              "file_name" character varying(128) NOT NULL,
                                              "description" character varying(255) DEFAULT NULL::character varying,
                                              "content" text NOT NULL,
                                              "is_folder" smallint NOT NULL DEFAULT 0,
                                              "parent_path" character varying(512) NOT NULL DEFAULT ''::character varying,
                                              "version" integer NOT NULL DEFAULT 1,
                                              "hash" character(32) DEFAULT NULL::bpchar,
                                              "active_flag" smallint NOT NULL DEFAULT 1,
                                              "file_type" character varying(16) NOT NULL DEFAULT 'BACKEND'::character varying,
                                              "sort" integer DEFAULT 0,
                                              "status" integer DEFAULT 1,
                                              "revision" integer DEFAULT 0,
                                              "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                              "is_deleted" smallint NOT NULL DEFAULT 0,
                                              "created_by" character varying(36) DEFAULT NULL::character varying,
                                              "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                              "updated_by" character varying(36) DEFAULT NULL::character varying,
                                              "updated_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                              CONSTRAINT "pk_ydsz_gen_template" PRIMARY KEY (id),
                                              CONSTRAINT "uk_ydsz_gen_template_group_file" UNIQUE (group_id, file_name)
);
COMMENT ON TABLE "public"."ydsz_gen_template" IS '代码生成器模板';
COMMENT ON COLUMN "public"."ydsz_gen_template"."id" IS '主键 ID';
COMMENT ON COLUMN "public"."ydsz_gen_template"."group_id" IS '关联模板分组 ID';
COMMENT ON COLUMN "public"."ydsz_gen_template"."file_name" IS '文件名（如 entity.vm、vue/api.vm）';
COMMENT ON COLUMN "public"."ydsz_gen_template"."description" IS '模板用途描述';
COMMENT ON COLUMN "public"."ydsz_gen_template"."content" IS '模板内容（Velocity 语法）';
COMMENT ON COLUMN "public"."ydsz_gen_template"."is_folder" IS '是否为虚拟文件夹标记（0=否 1=是）';
COMMENT ON COLUMN "public"."ydsz_gen_template"."parent_path" IS '父路径（如 vue/ 表示前端子目录）';
COMMENT ON COLUMN "public"."ydsz_gen_template"."version" IS '当前版本号';
COMMENT ON COLUMN "public"."ydsz_gen_template"."hash" IS '内容 MD5 哈希（版本对比用）';
COMMENT ON COLUMN "public"."ydsz_gen_template"."active_flag" IS '是否启用（0=否 1=是）';
COMMENT ON COLUMN "public"."ydsz_gen_template"."file_type" IS '模板类型（BACKEND/FRONTEND）';
COMMENT ON COLUMN "public"."ydsz_gen_template"."created_by" IS '创建者用户 ID';
COMMENT ON COLUMN "public"."ydsz_gen_template"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ydsz_gen_template"."updated_by" IS '更新者用户 ID';
COMMENT ON COLUMN "public"."ydsz_gen_template"."updated_at" IS '更新时间';
CREATE INDEX "idx_ydsz_gen_template_group" ON "public"."ydsz_gen_template" USING btree ("group_id" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_gen_column_meta" CASCADE;

CREATE TABLE "public"."ydsz_gen_column_meta" (
                                                 "id" character varying(36) NOT NULL,
                                                 "table_meta_id" character varying(36) NOT NULL,
                                                 "column_name" character varying(128) NOT NULL,
                                                 "data_type" character varying(64) NOT NULL,
                                                 "column_size" integer,
                                                 "is_nullable" smallint NOT NULL DEFAULT 1,
                                                 "is_pk" smallint NOT NULL DEFAULT 0,
                                                 "comment" character varying(255) DEFAULT NULL::character varying,
                                                 "override_java_type" character varying(64) DEFAULT NULL::character varying,
                                                 "override_field_name" character varying(64) DEFAULT NULL::character varying,
                                                 "is_dto_skipped" smallint NOT NULL DEFAULT 0,
                                                 "is_vo_skipped" smallint NOT NULL DEFAULT 0,
                                                 "is_query_skipped" smallint NOT NULL DEFAULT 0,
                                                 "extra_config" jsonb,
                                                 "sort" integer DEFAULT 0,
                                                 "status" integer DEFAULT 1,
                                                 "revision" integer DEFAULT 0,
                                                 "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                                 "is_deleted" smallint NOT NULL DEFAULT 0,
                                                 "created_by" character varying(36) DEFAULT NULL::character varying,
                                                 "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                 "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                 "updated_at" timestamp without time zone DEFAULT now(),
                                                 CONSTRAINT "pk_ydsz_gen_column_meta" PRIMARY KEY (id),
                                                 CONSTRAINT "uk_ydsz_gen_column_meta_table_column" UNIQUE (table_meta_id, column_name)
);
COMMENT ON TABLE "public"."ydsz_gen_column_meta" IS '列元数据缓存（含人工覆盖配置）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."id" IS '主键 ID';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."table_meta_id" IS '所属表元数据 ID';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."column_name" IS '物理列名';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."data_type" IS '物理数据类型';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."column_size" IS '字段长度';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."is_nullable" IS '是否可为空（0=否 1=是）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."is_pk" IS '是否为主键（0=否 1=是）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."comment" IS '字段注释';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."override_java_type" IS '人工覆盖 Java 类型（为空则使用自动映射）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."override_field_name" IS '人工覆盖字段名（为空则使用自动命名）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."is_dto_skipped" IS '是否在 DTO 中跳过（0=否 1=是）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."is_vo_skipped" IS '是否在 VO 中跳过（0=否 1=是）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."is_query_skipped" IS '是否在 Query 中跳过（0=否 1=是）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."extra_config" IS '扩展配置 JSON（枚举值、校验规则等）';
COMMENT ON COLUMN "public"."ydsz_gen_column_meta"."created_at" IS '创建时间';
CREATE INDEX "idx_ydsz_gen_column_meta_table" ON "public"."ydsz_gen_column_meta" USING btree ("table_meta_id" ASC NULLS LAST);

DROP TABLE IF EXISTS "public"."ydsz_gen_history_file" CASCADE;

CREATE TABLE "public"."ydsz_gen_history_file" (
                                                  "id" character varying(36) NOT NULL,
                                                  "history_id" character varying(36) NOT NULL,
                                                  "file_path" character varying(512) NOT NULL,
                                                  "original_backup_path" character varying(512) DEFAULT NULL::character varying,
                                                  "file_hash" character(32) DEFAULT NULL::bpchar,
                                                  "action" character varying(16) NOT NULL DEFAULT 'CREATED'::character varying,
                                                  "sort" integer DEFAULT 0,
                                                  "status" integer DEFAULT 1,
                                                  "revision" integer DEFAULT 0,
                                                  "tenant_id" character varying(36) NOT NULL DEFAULT '0'::character varying,
                                                  "is_deleted" smallint NOT NULL DEFAULT 0,
                                                  "created_by" character varying(36) DEFAULT NULL::character varying,
                                                  "created_at" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                  "updated_by" character varying(36) DEFAULT NULL::character varying,
                                                  "updated_at" timestamp without time zone DEFAULT now(),
                                                  CONSTRAINT "pk_ydsz_gen_history_file" PRIMARY KEY (id)
);
COMMENT ON TABLE "public"."ydsz_gen_history_file" IS '生成历史文件明细';
COMMENT ON COLUMN "public"."ydsz_gen_history_file"."id" IS '主键 ID';
COMMENT ON COLUMN "public"."ydsz_gen_history_file"."history_id" IS '所属任务 ID';
COMMENT ON COLUMN "public"."ydsz_gen_history_file"."file_path" IS '生成文件路径';
COMMENT ON COLUMN "public"."ydsz_gen_history_file"."original_backup_path" IS '原文件备份路径（用于回滚）';
COMMENT ON COLUMN "public"."ydsz_gen_history_file"."file_hash" IS '文件内容 MD5 哈希';
COMMENT ON COLUMN "public"."ydsz_gen_history_file"."action" IS '文件操作类型（CREATED/UPDATED/UNCHANGED）';
COMMENT ON COLUMN "public"."ydsz_gen_history_file"."created_at" IS '创建时间';
CREATE INDEX "idx_ydsz_gen_history_file_history" ON "public"."ydsz_gen_history_file" USING btree ("history_id" ASC NULLS LAST);

